def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])

    def runs(indices):
        result = []
        for x in indices:
            if not result or x != result[-1][-1] + 1:
                result.append([x])
            else:
                result[-1].append(x)
        return result

    row_runs = runs([r for r in range(h) if any(grid[r])])
    col_runs = runs([c for c in range(w) if any(grid[r][c] for r in range(h))])
    bh = max(map(len, row_runs))
    bw = max(map(len, col_runs))
    row_blocks = [x for x in row_runs if len(x) == bh]
    col_blocks = [x for x in col_runs if len(x) == bw]

    if bh < 3 or bw < 3 or not row_blocks or not col_blocks:
        return [row[:] for row in grid]

    tiles = [
        (rb, cb)
        for rb in row_blocks
        for cb in col_blocks
    ]

    border = Counter()
    interior = Counter()
    for rb, cb in tiles:
        for i in range(bh):
            for j in range(bw):
                value = grid[rb[0] + i][cb[0] + j]
                if i in (0, bh - 1) or j in (0, bw - 1):
                    border[value] += 1
                else:
                    interior[value] += 1

    if not border or not interior:
        return [row[:] for row in grid]

    border_color = border.most_common(1)[0][0]
    neutral_color = interior.most_common(1)[0][0]
    special = set(interior) - {border_color, neutral_color}
    out = [row[:] for row in grid]

    # Extend repeated special colors across the gaps between tiles in each row.
    for rb in row_blocks:
        for i in range(1, bh - 1):
            y = rb[0] + i
            for j in range(1, bw - 1):
                for color in special:
                    positions = [
                        k for k, cb in enumerate(col_blocks)
                        if grid[y][cb[0] + j] == color
                    ]
                    if len(positions) >= 2:
                        for a, b in zip(positions, positions[1:]):
                            for gap in range(a, b):
                                for x in range(col_blocks[gap][-1] + 1,
                                               col_blocks[gap + 1][0]):
                                    if out[y][x] == 0:
                                        out[y][x] = color

    # Extend repeated special colors across the gaps between tiles in each column.
    for cb in col_blocks:
        for j in range(1, bw - 1):
            x = cb[0] + j
            for i in range(1, bh - 1):
                for color in special:
                    positions = [
                        k for k, rb in enumerate(row_blocks)
                        if grid[rb[0] + i][x] == color
                    ]
                    if len(positions) >= 2:
                        for a, b in zip(positions, positions[1:]):
                            for gap in range(a, b):
                                for y in range(row_blocks[gap][-1] + 1,
                                               row_blocks[gap + 1][0]):
                                    if out[y][x] == 0:
                                        out[y][x] = color

    return out
